        _ => self
            .get_syntax_for_file_extension(file_name, &mapping.ignored_suffixes)?
            .ok_or_else(|| {
                Error::UndetectedSyntax(crate::preprocessor::sanitize_for_terminal(
                    &path.to_string_lossy(),
                ))
            }),
    }
}

