        for (path, expected) in [
            (r"C:\dir\file.myconf", Some(MappingTarget::MapTo("INI"))),
            (r"\\?\C:\dir\file.myconf", Some(MappingTarget::MapTo("INI"))),
            (r"\\?\D:\dir\file.myconf", None),
            (
                r"\\?\C:\literal\file.myconf",
